import json
import re
import sys

## XXX TODO : create python enums for relkind, target...

prefix = """

// This stencil library was generated by stencil-builder.py
// Do not edit by hand, especially if you don't know what you are doing.

typedef enum Relkind {
    RELKIND_R_X86_64_64,
    RELKIND_REJUMP,
    RELKIND_R_AARCH64_MOVW_UABS_G0_NC,
    RELKIND_R_AARCH64_MOVW_UABS_G1_NC,
    RELKIND_R_AARCH64_MOVW_UABS_G2_NC,
    RELKIND_R_AARCH64_MOVW_UABS_G3,
    RELKIND_R_AARCH64_JUMP26,
    RELKIND_R_AARCH64_CALL26
} Relkind;

typedef enum Target {
    TARGET_CONST_ISNULL,
    TARGET_CONST_VALUE,
    TARGET_RESULTNUM,
    TARGET_ATTNUM,
    TARGET_OP,
    TARGET_NEXT_CALL,
    TARGET_FORCE_NEXT_CALL,
    TARGET_FUNC_CALL,
    TARGET_FUNC_INFO,
    TARGET_FUNC_NARGS,
    TARGET_FUNC_ARG,
    TARGET_JUMP_DONE,
    TARGET_JUMP_NULL,
    TARGET_RESULTSLOT_VALUES,
    TARGET_RESULTSLOT_ISNULL,
    TARGET_REGISTER_ISNULL,
    TARGET_REGISTER_VALUE,
    TARGET_MakeExpandedObjectReadOnlyInternal,  // TODO : replace this and followings with a TARGET_FUNCTION_CALL and a Patch::function_name ?
    TARGET_slot_getsomeattrs_int,
    TARGET_ExecEvalScalarArrayOp,               // TODO : used as is, should be reimplemented but I wanted to show it can be quick this way
    TARGET_ExecEvalSysVar,                      // can it stay as is ?
    TARGET_ExecEvalSQLValueFunction,            // should be fine too
    TARGET_ExecEvalParamExec,                   // should be fine too
    TARGET_ExecEvalParamExtern,                 // should be fine too
    TARGET_CurrentMemoryContext,
} Target;

typedef void (*RegisterContractFunction)(ExprState *expression, ExprEvalStep *op, void *context);

typedef struct Patch {
    const uint64_t offset; // Do we need length ?
    const Relkind relkind;
    const Target target;
    const uint64_t addend;
} Patch;

typedef struct Stencil {
    size_t code_size;
    const unsigned char *code;
    size_t patch_size;
    const Patch *patches;
    RegisterContractFunction registers_contract;
} Stencil;

"""


## Not fond of this, it would be better as a fully static array. will do for now.
prefix_initializer = """
void initialize_stencils() {
    for (int i = 0 ; i < EEOP_LAST ; i++) {
        // mark all stencils as uninitialized
        stencils[i].code_size = -1;
    }
"""

postfix_initializer = "}"

class Patch(object):
    def __init__ (self, target, kind, offset, addend):
        self.target = target
        # XXX FIXME this is lazy
        if self.target == "op":
            self.target = "OP"
        self.kind = kind
        self.offset = offset
        self.addend = addend

    def dump_patch(self, out_fd):
        out_fd.write("{%s, RELKIND_%s, TARGET_%s, %s}," % (self.offset, self.kind, self.target, self.addend))

class Stencil(object):
    eeop_last_offset = 1

    def __init__ (self, name, code, start, end, arch):
        self.name = name
        self.code = code
        self.start = start
        self.end = end
        self.arch = arch
        self.patches = []
        self.reassigned_id = None
        self.registers_contract = None
        if self.name.startswith("extra_"):
            self.mark_extra()

    def mark_extra(self):
        self.reassigned_id = f"EEOP_LAST+{Stencil.eeop_last_offset}"
        Stencil.eeop_last_offset += 1

    def add_patch(self, patch):
        self.patches.append(patch)
        patch.offset -= self.start

    def _strip_final_next_call(self):
        # first, find the NEXT_CALL patch
        next_call_patch = None
        used_targets = set()
        for patch in self.patches:
            used_targets.add(patch.target)
            if patch.target == "NEXT_CALL":
                next_call_patch = patch

        if next_call_patch is None:
            return

        if next_call_patch != self.patches[-1]:
            return

        if self.arch == "x86_64":
            # ok, so we must identify that pattern at patch.offset-2 : movabs $0x0,%rax ; jmp *%rax
            # aka 48 b8 00 00 00 00 00 00 00 00 ff e0
            amd64prefix = self.code[next_call_patch.offset - 2:next_call_patch.offset]
            amd64postfix = self.code[next_call_patch.offset + 8:next_call_patch.offset + 10]
            if amd64prefix == [0x48, 0xb8] and amd64postfix == [0xff, 0xe0]:
                # now we know where it ends : at patch.offset - 2
                self.code = self.code[:next_call_patch.offset - 2]
                self.patches = self.patches[:-1]
            # XXX TODO : extremely hazardous hack
            elif False and self.code[-2:] == [0xff, 0xe0] and not "TARGET_JUMP_DONE" in used_targets:
                # last opcode is jmp *rax, remove it because we should never jump somewhere else
                self.code = self.code[:-2]
        elif self.arch == "aarch64":
            ## if next call patch is in the last instruction, just remove it
            if next_call_patch.offset + 4 == len(self.code):
                self.code = self.code[:len(self.code) - 4]
                self.patches = self.patches[:-1]

    def strip_code(self):
        # first, try to get rid of final next_call
        self._strip_final_next_call()
        # and now for specific optimizations
        if self.arch == "x86_64" and False:
            # now, try to find out a movabs XX, %rax ; jmp *%rax sequence
            mov_and_jmp = b"\x48\xb8\x00\x00\x00\x00\x00\x00\x00\x00\xff\xe0"
            patch_offset = 2
            code = bytes(self.code)
            while mov_and_jmp in code:
                idx = code.index(mov_and_jmp)
                # replace it with nops
                code = code[:idx] + b"\x90" * len(mov_and_jmp) + code[idx+len(mov_and_jmp):]
                # move the corresponding patch to the beginning of this beautiful hole
                for patch in self.patches:
                    if patch.offset == idx+patch_offset:
                        patch.offset = idx
                        patch.kind = 'REJUMP'
            self.code = [x for x in code]

    def dump_code(self, out_fd):
        out_fd.write("const unsigned char %s__code[%s] = {%s};\n" % (self.name, len(self.code), ", ".join([hex(x) for x in self.code])))

    def dump_patches(self, out_fd):
        if len(self.patches) == 0:
            out_fd.write("// No patch for %s\n" % self.name)
        else:
            out_fd.write("const Patch %s__patches[%s] = {" % (self.name, len(self.patches)))
            for patch in self.patches:
                patch.dump_patch(out_fd)
            out_fd.write("};\n")

    def dump_globals(self, out_fd):
        self.dump_code(out_fd)
        self.dump_patches(out_fd)
        self.dump_registers_contract(out_fd)
        if self.name.startswith("extra_"):
            out_fd.write(f"const unsigned int {self.name}__opcode = {self.reassigned_id};\n")

    def dump_registers_contract(self, out_fd):
        if self.registers_contract is None:
            return

        out_fd.write("void stencil_registers_contract__%s(ExprState *expression, ExprEvalStep *op, void *context) {\n" % self.name)
        # Now we must play. Parsing it here, it's a bit late, but good enough for the PoC
        line_fcinfo_re = re.compile("^EXPECT_FCINFO (.*)$")
        line_memory_re = re.compile("^(EXPECT|WRITE) in (-?[0-9]+) null:(.*) value:(.*)$")
        line_trash_re = re.compile("^(TRASH) (-?[0-9]+)$")
        for line in self.registers_contract.strip().splitlines():
            if m := line_fcinfo_re.match(line):
                out_fd.write("  copyjit_register_fcinfo_access(%s, context);\n" % m.groups()[0])
            elif m := line_memory_re.match(line):
                if m.groups()[0] == "EXPECT":
                    out_fd.write("  copyjit_register_memory_read_access(%s, %s, %s, context);\n" % (m.groups()[1], m.groups()[2], m.groups()[3]))
                if m.groups()[0] == "WRITE":
                    out_fd.write("  copyjit_register_memory_write_access(%s, %s, %s, context);\n" % (m.groups()[1], m.groups()[2], m.groups()[3]))
            elif m := line_trash_re.match(line):
                out_fd.write("  copyjit_register_memory_write_access(%s, NULL, NULL, context);\n" % m.groups()[1])
        out_fd.write("}\n")

    def dump_initializer(self, out_fd):
        name_in_c = self.name
        if self.reassigned_id is not None:
            name_in_c = self.reassigned_id
        out_fd.write(f"// Code for {self.name}\n")
        if len(self.patches) == 0:
            out_fd.write("stencils[%s].code_size = %s; stencils[%s].code = %s__code; stencils[%s].patch_size = 0;\n" % (name_in_c, len(self.code), name_in_c, self.name, name_in_c))
        else:
            out_fd.write("stencils[%s].code_size = %s; stencils[%s].code = %s__code;\n" % (name_in_c, len(self.code), name_in_c, self.name))
            out_fd.write("stencils[%s].patch_size = %s; stencils[%s].patches = %s__patches;\n" % (name_in_c, len(self.patches), name_in_c, self.name))
        if self.registers_contract is not None:
            out_fd.write("stencils[%s].registers_contract = &stencil_registers_contract__%s;\n" % (name_in_c, self.name))
        else:
            out_fd.write("stencils[%s].registers_contract = NULL;\n" % name_in_c)
        out_fd.write(f"// End of code for {self.name}\n\n")

class ExtraStencil(Stencil):
    def dump_initializer(self, out_fd):
        if len(self.patches) == 0:
            out_fd.write("struct Stencil %s = { .code_size = %s, .code = %s__code, .patch_size = 0; };\n" % (self.name, len(self.code), self.name))
        else:
            out_fd.write("struct Stencil %s = { .code_size = %s, .code = %s__code, .patch_size = %s, .patches = %s__patches };\n" % (self.name, len(self.code), self.name, len(self.patches), self.name))

def sections_iterator(sections, major):
    for section in sections:
        section = section["Section"]
        if major < 15:
            yield (section["Name"]["Value"], section)
        else:
            yield (section["Name"]["Name"], section)

def relocations_iterator(relocations, major):
    for relocation in relocations:
        relocation = relocation["Relocation"]
        if major < 15:
            yield (relocation["Type"]["Value"], relocation["Symbol"]["Value"], relocation["Offset"], relocation["Addend"], relocation)
        else:
            yield (relocation["Type"]["Name"], relocation["Symbol"]["Name"], relocation["Offset"], relocation["Addend"], relocation)

def symbols_iterator(symbols, major):
    for symbol in symbols:
        symbol = symbol["Symbol"]
        if major < 15:
            yield (symbol["Name"]["Value"], symbol["Value"], symbol["Size"], symbol)
        else:
            yield (symbol["Name"]["Name"], symbol["Value"], symbol["Size"], symbol)

def generate_stencil(readobj_major, in_filename, out_filename):
    objdump = json.load(open(in_filename, "r"))
    stencils_o = objdump[0]
    if readobj_major < 15 and type(stencils_o) == dict:
        stencils_o = stencils_o[list(stencils_o.keys())[0]]
    print(stencils_o.keys())
    arch = stencils_o["FileSummary"]["Arch"]
    stencils = []
    ## selectors_only_stencils = set()
    stencil_selectors = {}  # stencil name => {selector id => selector info, varying type...}

    sections_dict = {}
    for (section_name, section) in sections_iterator(stencils_o["Sections"], readobj_major):
        sections_dict[section_name] = section

    for section_name in (".ltext", ".text"):
        if section_name in sections_dict:
            section = sections_dict[section_name]
            data = section["SectionData"]["Bytes"]
            print("iterating symbols")
            for (symbol_name, symbol_offset, symbol_size, symbol) in symbols_iterator(section["Symbols"], readobj_major):
                print("... symbol")
                if symbol_name.startswith("stencil_"):
                    print("iterating symbols => stencil")
                    end = symbol_offset + symbol_size
                    stencils.append(Stencil(symbol_name[8:], data[symbol_offset:end], symbol_offset, end, arch))
                elif symbol_name.startswith("extra_"):
                    print("iterating symbols => extra")
                    end = symbol_offset + symbol_size
                    stencil = Stencil(symbol_name, data[symbol_offset:end], symbol_offset, end, arch)
                    stencil.mark_extra()
                    stencils.append(stencil)
                else:
                    print(f"unknown symbol {symbol_name}")


    for section_name in (".rela.ltext", ".rela.text"):
        if section_name in sections_dict:
            section = sections_dict[section_name]
            for (relkind, target, code_offset, addend, relocation) in relocations_iterator(section["Relocations"], readobj_major):
                patch = Patch(target, relkind, code_offset, addend)

                # match the patch to a stencil
                for stencil in stencils:
                    if stencil.start <= patch.offset and stencil.end > patch.offset:
                        stencil.add_patch(patch)
                        break
                else:
                    raise Exception("Patch not matched to a stencil")

    if '.ldata' in sections_dict:
        section = sections_dict['.ldata']
        rela_ldata = sections_dict['.rela.ldata']
        # each symbol is a selector or a register contract for a stencil
        print("Iterating symbols for selectors")
        selector_name_regex = re.compile(r"^selector_stencil_(.*)__(.+)$")
        register_contract_regex = re.compile(r"^register_contract_(.*)$")
        selector_offset = 0
        for (symbol_name, symbol_offset, symbol_size, symbol) in symbols_iterator(section["Symbols"], readobj_major):
            print(f"Got symbol {symbol_name} for selectors/contracts")
            if m := selector_name_regex.match(symbol_name):
                print(m.groups())
                stencil_name, selector_id = m.groups()
                if not stencil_name in stencil_selectors:
                    stencil_selectors[stencil_name] = {}
                assert selector_id not in stencil_selectors[stencil_name]

                # Now we must go to .rela.ldata to get some infos
                matching_reloc = rela_ldata['Relocations'][selector_offset]['Relocation']
                print(matching_reloc)
                reloc_section = sections_dict[matching_reloc['Symbol']['Name']]

                # Now extract from SectionData to stencil_selectors, easy peasy
                selector_code = ""
                i = matching_reloc['Addend']
                while reloc_section["SectionData"]["Bytes"][i] != 0:
                    selector_code += chr(reloc_section["SectionData"]["Bytes"][i])
                    i += 1
                # must modify the corresponding stencil to let it know it's not a normal one
                for stencil in stencils:
                    if stencil.name == stencil_name + "__" + str(selector_id):
                        stencil.mark_extra()
                        stencil_selectors[stencil_name][selector_id] = {"code": selector_code, "stencil": stencil}
            elif m := register_contract_regex.match(symbol_name):
                stencil_name = m.groups()[0]
                print(m.groups())

                # Now we must go to .rela.ldata to get some infos
                matching_reloc = rela_ldata['Relocations'][selector_offset]['Relocation']
                print(matching_reloc)
                reloc_section = sections_dict[matching_reloc['Symbol']['Name']]
                # Now extract from SectionData to stencil_selectors, easy peasy
                contract_content = ""
                i = matching_reloc['Addend']
                while reloc_section["SectionData"]["Bytes"][i] != 0:
                    contract_content += chr(reloc_section["SectionData"]["Bytes"][i])
                    i += 1
                print(contract_content)
                for stencil in stencils:
                    if stencil.name == stencil_name:
                        stencil.registers_contract = contract_content

            selector_offset += 1
        print(stencil_selectors)

    with open(out_filename, "w") as out_fd:
        out_fd.write(prefix)

        out_fd.write(f"\nStencil stencils[EEOP_LAST+{Stencil.eeop_last_offset}];\n")

        out_fd.write("\nint dispatch_opcode(ExprEvalStep *op) {\n")
        out_fd.write("switch(op->opcode) {\n")
        for (stencil_name, selectors) in stencil_selectors.items():
            out_fd.write(f"    case {stencil_name}:\n")
            default_id = None
            print(selectors)
            for selector in selectors.keys():
                # must make sure default is last
                if selectors[selector]["code"] == "default":
                   default_id = selector
                   continue
                print(f"==> default_id = {default_id}")
                out_fd.write(f"        if ({selectors[selector]['code']}) return {selectors[selector]['stencil'].reassigned_id};\n")
            if default_id is not None:
                out_fd.write(f"        else return {selectors[default_id]['stencil'].reassigned_id};\n")
            else:
                out_fd.write(f"        else return {stencil_name};\n")
        out_fd.write("    default: return op->opcode;\n")
        out_fd.write("  }\n")
        out_fd.write("}\n")

        for stencil in stencils:
            stencil.strip_code()
            stencil.dump_globals(out_fd)


        out_fd.write(prefix_initializer)
        for stencil in stencils:
            stencil.dump_initializer(out_fd)
        out_fd.write(postfix_initializer)

if __name__ == "__main__":
    # args readobj-version source.json target.c
    readobj_version = sys.argv[1]
    major_version = int(readobj_version.split('.')[0])
    filename = sys.argv[2]
    output = sys.argv[3]
    generate_stencil(major_version, filename, output)
